195	    /** The one public static method of that name and arity, or null. */
196	    private static Method soleMethod(String cls, String method, int arity) {
197	        Method found = null;
198	        try {
199	            for (Method x : Class.forName(cls, false, BuiltinPrimitiveRewriter.class.getClassLoader()).getMethods())
200	                if (x.getName().equals(method) && Modifier.isStatic(x.getModifiers()) && x.getParameterTypes().length == arity) {
201	                    if (found != null) return null;
202	                    found = x;
203	                }
204	        } catch (ClassNotFoundException e) { } catch (LinkageError e) { }
205	        return found;
206	    }
