209	    public static boolean namesHelpers(java.io.File file) {
210	        try {
211	            return new String(java.nio.file.Files.readAllBytes(file.toPath()), "UTF-8").contains("\"" + HELPERS);
212	        } catch (java.io.IOException e) { return false; }
213	    }
